import PropTypes from "prop-types";
import React from "react";

import { compose } from "redux";
import { connect } from "react-redux";
import {
  commonRulesMapDisToProps,
  commonRulesReducers,
  commonRulesSelector,
} from "./CommonRuleRedux";
import { number, required } from "./ValidationUtil";
import {
  toTitleCase,
  validateInput,
  getNumberDataTypes,
  convertToStringOfBool,
  convertToBool,
} from "./CommonRuleFunctions";
import applyReducers from "@traveloka/soya-components/lib/legacy/applyReducers";
import DropdownInput from "./DropdownInput";
import TextInput from "./TextInput";
import { Button } from "@traveloka/soya-components";

import * as style from "./CommonRule.styles";

class ActionsModal extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      existingValue: props.existingValue
        ? convertToStringOfBool(props.existingValue)
        : this.getDefaultValue(),
    };
  }

  getDefaultValue() {
    const { ruleStructures } = this.props;
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);

    for (const i in expressionStructure) {
      if (expressionStructure[i].type === "procedure") {
        const defaultValue = Object.assign(
          this.getAdditionalFieldValue(expressionStructure[i].id)
        );
        defaultValue.root = expressionStructure[i].id;
        return defaultValue;
      }
    }
  }

  getAdditionalFieldValue(root) {
    let existingValue;
    if (this.state && this.state.existingValue) {
      existingValue = this.state.existingValue;
    }
    const { ruleStructures } = this.props;
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    const dataTypeStructure = JSON.parse(ruleStructures.dataTypeStructure);

    const result = {};
    for (const i in expressionStructure[root].input) {
      const type = expressionStructure[root].input[i];
      if (!dataTypeStructure[type].valueOption.length) {
        result[expressionStructure[root].property[i]] = !existingValue
          ? ""
          : existingValue[expressionStructure[root].property[i]];
      } else {
        if (type === "Boolean") {
          result[expressionStructure[root].property[i]] = "true";
        } else {
          result[expressionStructure[root].property[i]] =
            dataTypeStructure[type].valueOption[0];
        }
      }
    }
    return result;
  }

  getAdditionalField(root) {
    const additionalFieldToForm = [];
    const { ruleStructures } = this.props;
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    const dataTypeStructure = JSON.parse(ruleStructures.dataTypeStructure);
    const { existingValue } = this.state;
    const numberTypes = getNumberDataTypes();
    for (const i in expressionStructure[root].property) {
      const additionalField = expressionStructure[root].property[i];
      const type = expressionStructure[root].input[i];
      additionalFieldToForm.push(<label>{additionalField}</label>);
      additionalFieldToForm.push(<br />);
      if (numberTypes.includes(type)) {
        additionalFieldToForm.push(
          <TextInput
            key={i}
            name={additionalField}
            placeholder={name}
            onChange={this.handleChangeAdditionalField}
            validators={[required, number, validateInput]}
            value={existingValue[additionalField]}
            validationFormat={dataTypeStructure[type].validationFormat}
          />
        );
      } else if (type === "String" || type === "Byte") {
        additionalFieldToForm.push(
          <TextInput
            key={i}
            name={additionalField}
            placeholder={name}
            onChange={this.handleChangeAdditionalField}
            validators={[required]}
            value={existingValue[additionalField]}
          />
        );
      } else if (type === "Boolean") {
        const items = [
          { value: "true", label: "True" },
          { value: "false", label: "False" },
        ];
        additionalFieldToForm.push(
          <DropdownInput
            key={i}
            name={additionalField}
            onChange={this.handleChangeAdditionalField}
            items={items}
            value={existingValue[additionalField]}
          />
        );
      } else {
        if (dataTypeStructure[type].valueOption.length > 0) {
          const items = [];
          for (const j in dataTypeStructure[type].valueOption) {
            const option = {};
            option.value = dataTypeStructure[type].valueOption[j];
            option.label = toTitleCase(
              String(dataTypeStructure[type].valueOption[j])
            );
            items.push(option);
          }

          additionalFieldToForm.push(
            <DropdownInput
              key={i}
              name={additionalField}
              onChange={this.handleChangeAdditionalField}
              items={items}
              value={existingValue[additionalField]}
            />
          );
        } else {
          additionalFieldToForm.push(
            <TextInput
              key={i}
              name={additionalField}
              placeholder={name}
              onChange={this.handleChangeAdditionalField}
              validators={[required, validateInput]}
              validationFormat={dataTypeStructure[type].validationFormat}
              value={existingValue[additionalField]}
            />
          );
        }
      }
    }
    return additionalFieldToForm;
  }

  handleChangeRoot = (name, value) => {
    const stateValue = Object.assign(this.getAdditionalFieldValue(value));
    stateValue[name] = value;
    this.setState({ existingValue: stateValue });
  };

  handleChangeAdditionalField = (name, value, isValid) => {
    const { existingValue } = this.state;
    existingValue[name] = value;
    this.setState({ existingValue });
  };

  convertExistingValue(existingValue) {
    for (const i in existingValue) {
      if (existingValue[i] === "true") {
        existingValue[i] = true;
      } else if (existingValue[i] === "false") {
        existingValue[i] = false;
      }
    }
    return existingValue;
  }

  getOptions() {
    const { ruleStructures } = this.props;
    const expressionOptions = [];
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    const formatterStructure = JSON.parse(ruleStructures.formatterStructure);

    for (const i in expressionStructure) {
      if (expressionStructure[i].type === "procedure") {
        expressionOptions.push({
          value: i,
          label: toTitleCase(formatterStructure[i].label),
        });
      }
    }
    return expressionOptions;
  }

  handleCancel = () => {
    const { onCancel } = this.props;
    onCancel();
  };

  handleSave = () => {
    const { onSave } = this.props;
    const { existingValue } = this.state;
    onSave(convertToBool(existingValue));
  };

  render() {
    const expressionOptions = this.getOptions();
    const { existingValue } = this.state;
    const additionalField = this.getAdditionalField(existingValue.root);
    return (
      <div>
        <div>
          <label>{"Expressions"}</label>
          <br />
          <DropdownInput
            name="root"
            value={existingValue.root}
            items={expressionOptions}
            onChange={this.handleChangeRoot}
          />
        </div>
        <div>{additionalField}</div>
        <div className={style.modalFooter}>
          <Button onClick={this.handleCancel} color="link">
            {"Close"}
          </Button>
          <Button onClick={this.handleSave} color="blue">
            {"OK"}
          </Button>
        </div>
      </div>
    );
  }
}

ActionsModal.propTypes = {
  existingValue: PropTypes.object,
  ruleStructures: PropTypes.string,
  onCancel: PropTypes.func.isRequired,
  onSave: PropTypes.func.isRequired,
};

const mapStateToProps = (state, ownProps) => ({
  ruleStructures: commonRulesSelector.getRuleStructures(state),
});

export default compose(
  applyReducers(commonRulesReducers),
  connect(mapStateToProps, commonRulesMapDisToProps)
)(ActionsModal);
